WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_reading_paragraph'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '段落概括', 'kp-sl-reading-paragraph', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "段落概括：划定核心意群"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "首尾句是金子，中间段是沙子。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、段落结构扫描"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读段落第一句话] --> B{是总起句吗?}\nB -- 是(抛出论点/对策) --> C[直接划下核心词, 下面的例子一概略读]\nB -- 不是(讲故事/引述) --> D[直接跳到段落最后一句话]\nD --> E{是总结句吗?}\nE -- 是(因此,总之) --> F[划下核心词]\nE -- 都没有 --> G[这是个并列散段, 必须挑出其中所有的动词+名词组合自行概括]"}}]}$$ AS jsonb), NULL, '段落概括的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "阅读理解", "段落结构"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_reading_paragraph", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
